<parameter name="contents">import bcrypt from 'bcrypt';
import { getDb } from './db.js';

const SALT_ROUNDS = 10;
const MAX_ATTEMPTS = 5;
const ATTEMPT_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

export async function hashPassword(password) {
  return bcrypt.hash(password, SALT_ROUNDS);
}

export async function verifyPassword(password, hash) {
  return bcrypt.compare(password, hash);
}

export async function createUser(email, password) {
  const db = getDb();
  const passwordHash = await hashPassword(password);

  try {
    const result = await db.run(
      'INSERT INTO users (email, password_hash) VALUES (?, ?)',
      [email, passwordHash]
    );
    return { id: result.lastID, email };
  } catch (err) {
    if (err.message.includes('UNIQUE constraint failed')) {
      throw new Error('Email already registered');
    }
    throw err;
  }
}

export async function findUserByEmail(email) {
  const db = getDb();
  return db.get('SELECT * FROM users WHERE email = ?', [email]);
}

export async function recordFailedAttempt(email) {
  const db = getDb();
  await db.run(
    'INSERT INTO failed_attempts (email, attempted_at) VALUES (?, CURRENT_TIMESTAMP)',
    [email]
  );
}

export async function clearFailedAttempts(email) {
  const db = getDb();
  await db.run('DELETE FROM failed_attempts WHERE email = ?', [email]);
}

export async function getFailedAttempts(email) {
  const db = getDb();
  const cutoffTime = new Date(Date.now() - ATTEMPT_WINDOW_MS).toISOString();

  const result = await db.all(
    'SELECT COUNT(*) as count FROM failed_attempts WHERE email = ? AND attempted_at > ?',
    [email, cutoffTime]
  );

  return result[0].count || 0;
}

export async function isRateLimited(email) {
  const attempts = await getFailedAttempts(email);
  return attempts >= MAX_ATTEMPTS;
}
