<parameter name="contents">import express from 'express';
import session from 'express-session';
import bodyParser from 'body-parser';
import { initDb } from './db.js';
import {
  createUser,
  findUserByEmail,
  verifyPassword,
  recordFailedAttempt,
  clearFailedAttempts
} from './auth.js';
import { requireAuth, rateLimitMiddleware } from './middleware.js';

const app = express();
const PORT = 3000;

app.use(bodyParser.json());

app.use(
  session({
    secret: 'your-secret-key-change-this',
    resave: false,
    saveUninitialized: false,
    cookie: {
      secure: false, // set to true in production with HTTPS
      httpOnly: true,
      maxAge: 1000 * 60 * 60 * 24 // 24 hours
    }
  })
);

app.post('/signup', async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: 'Email and password required' });
    }

    if (password.length < 8) {
      return res.status(400).json({ error: 'Password must be at least 8 characters' });
    }

    const user = await createUser(email, password);
    req.session.userId = user.id;

    res.status(201).json({ message: 'Account created', user });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.post('/login', rateLimitMiddleware, async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: 'Email and password required' });
    }

    const user = await findUserByEmail(email);

    if (!user) {
      await recordFailedAttempt(email);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const passwordMatch = await verifyPassword(password, user.password_hash);

    if (!passwordMatch) {
      await recordFailedAttempt(email);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    await clearFailedAttempts(email);
    req.session.userId = user.id;

    res.json({ message: 'Logged in successfully', user: { id: user.id, email: user.email } });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/logout', requireAuth, (req, res) => {
  req.session.destroy((err) => {
    if (err) {
      return res.status(500).json({ error: 'Failed to logout' });
    }
    res.json({ message: 'Logged out successfully' });
  });
});

app.get('/profile', requireAuth, async (req, res) => {
  try {
    const user = await require('./db.js').getDb().get('SELECT id, email FROM users WHERE id = ?', [req.session.userId]);
    res.json(user);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

async function start() {
  try {
    await initDb();
    app.listen(PORT, () => {
      console.log(`Server running on http://localhost:${PORT}`);
    });
  } catch (err) {
    console.error('Failed to start server:', err);
    process.exit(1);
  }
}

start();
